    private static PdfPCell addCheckboxCell(String label, boolean isChecked) {

        PdfPCell cell = new PdfPCell();
        // Unicode characters for checked and unchecked checkboxes
        String checkboxChar = isChecked ? "☑" : "☐";

        // Use a custom color for the checked checkbox
        BaseColor checkboxColor = isChecked ? new BaseColor(BaseColor.BLACK.getAlpha()) : null;

        // Set the label with the checkbox character and text
        cell.setPhrase(new Phrase(checkboxChar + " " + label, getFont(checkboxColor)));
        return cell;
    }

    private static Font getFont(BaseColor color) {
        Font font = new Font();
        font.setSize(12);
        font.setColor(color);
        return font;
    }

